// HeroSlides.jsx - Interactive Hero Slideshow
import React, { useState, useEffect } from 'react';

export default function HeroSlides(props) {
  const {
    slides = [
  {
    "id": "s1",
    "title": "Fast",
    "description": "Ship in minutes",
    "bgImage": "/img/1.png",
    "buttonText": "Start",
    "buttonUrl": "/start"
  },
  {
    "id": "s2",
    "title": "Flexible",
    "description": "Any framework",
    "bgColor": "#111827"
  }
],
    height = "450px",
    autoplay = true,
    autoplayInterval = 4000,
    transition = "slide",
    alignment = "center",
    showArrows = true,
    showDots = true,
    className = "",
    style = {},
    ...rest
  } = props;

  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    if (!autoplay || slides.length <= 1) return;
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % slides.length);
    }, autoplayInterval);
    return () => clearInterval(timer);
  }, [autoplay, slides.length, autoplayInterval]);

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + slides.length) % slides.length);
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % slides.length);
  };

  if (!slides || slides.length === 0) {
    return (
      <div style={{ height, display: "flex", alignItems: "center", justifyContent: "center", backgroundColor: "#0f172a", color: "#94a3b8", borderRadius: "16px", ...style }}>
        <p>No slides configured</p>
      </div>
    );
  }

  const currentSlide = slides[currentIndex] || slides[0];

  const textAlign = alignment === "center" ? "center" : alignment === "right" ? "right" : "left";
  const alignItems = alignment === "center" ? "center" : alignment === "right" ? "flex-end" : "flex-start";

  return (
    <div
      className={className}
      style={{
        position: "relative",
        width: "100%",
        height: height,
        overflow: "hidden",
        borderRadius: "16px",
        boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.2)",
        backgroundColor: currentSlide.bgColor || "#0f172a",
        ...style,
      }}
      {...rest}
    >
      {slides.map((slide, idx) => {
        const isActive = idx === currentIndex;
        return (
          <div
            key={slide.id || idx}
            style={{
              position: "absolute",
              inset: 0,
              opacity: isActive ? 1 : 0,
              transform: isActive ? "translateX(0px)" : transition === "fade" ? "none" : "translateX(40px)",
              transition: "all 0.7s cubic-bezier(0.4, 0, 0.2, 1)",
              pointerEvents: isActive ? "auto" : "none",
              backgroundImage: slide.bgImage ? `url(${slide.bgImage})` : undefined,
              backgroundSize: "cover",
              backgroundPosition: "center",
              backgroundColor: slide.bgColor || "#0f172a",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
            }}
          >
            {/* Gradient Overlay */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: "linear-gradient(to top, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.45) 50%, rgba(0, 0, 0, 0.3) 100%)",
              }}
            />

            {/* Slide Content */}
            <div
              style={{
                position: "relative",
                zIndex: 10,
                display: "flex",
                flexDirection: "column",
                alignItems: alignItems,
                textAlign: textAlign,
                padding: "48px",
                maxWidth: "750px",
                margin: alignment === "center" ? "0 auto" : alignment === "right" ? "0 0 0 auto" : "0",
              }}
            >
              <h2
                style={{
                  fontSize: "36px",
                  fontWeight: "800",
                  color: "#ffffff",
                  lineHeight: 1.2,
                  margin: "0 0 16px 0",
                  textShadow: "0 2px 4px rgba(0,0,0,0.5)",
                }}
              >
                {slide.title}
              </h2>

              {slide.description && (
                <p
                  style={{
                    fontSize: "16px",
                    color: "#e2e8f0",
                    lineHeight: 1.6,
                    margin: "0 0 24px 0",
                    maxWidth: "550px",
                    textShadow: "0 1px 2px rgba(0,0,0,0.5)",
                  }}
                >
                  {slide.description}
                </p>
              )}

              {slide.buttonText && (
                <a
                  href={slide.buttonUrl || "#"}
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "8px",
                    backgroundColor: "#ffffff",
                    color: "#0f172a",
                    fontWeight: "700",
                    fontSize: "14px",
                    padding: "12px 28px",
                    borderRadius: "10px",
                    textDecoration: "none",
                    boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.2)",
                  }}
                >
                  <span>{slide.buttonText}</span>
                  <span>→</span>
                </a>
              )}
            </div>
          </div>
        );
      })}

      {/* Navigation Arrows */}
      {showArrows && slides.length > 1 && (
        <>
          <button
            type="button"
            onClick={prevSlide}
            aria-label="Previous Slide"
            style={{
              position: "absolute",
              left: "16px",
              top: "50%",
              transform: "translateY(-50%)",
              zIndex: 20,
              width: "44px",
              height: "44px",
              borderRadius: "50%",
              backgroundColor: "rgba(0, 0, 0, 0.5)",
              color: "#ffffff",
              border: "1px solid rgba(255, 255, 255, 0.2)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
            }}
          >
            ‹
          </button>
          <button
            type="button"
            onClick={nextSlide}
            aria-label="Next Slide"
            style={{
              position: "absolute",
              right: "16px",
              top: "50%",
              transform: "translateY(-50%)",
              zIndex: 20,
              width: "44px",
              height: "44px",
              borderRadius: "50%",
              backgroundColor: "rgba(0, 0, 0, 0.5)",
              color: "#ffffff",
              border: "1px solid rgba(255, 255, 255, 0.2)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
            }}
          >
            ›
          </button>
        </>
      )}

      {/* Pagination Dots */}
      {showDots && slides.length > 1 && (
        <div
          style={{
            position: "absolute",
            bottom: "20px",
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 20,
            display: "flex",
            gap: "8px",
          }}
        >
          {slides.map((_, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => setCurrentIndex(idx)}
              aria-label={`Go to slide ${idx + 1}`}
              style={{
                width: idx === currentIndex ? "28px" : "10px",
                height: "10px",
                borderRadius: "5px",
                backgroundColor: idx === currentIndex ? "#ffffff" : "rgba(255, 255, 255, 0.4)",
                border: "none",
                cursor: "pointer",
                padding: 0,
                transition: "all 0.3s ease",
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

